import inspect
from functools import partial


class Injecter(object):

    class Target(object):
        def __init__(self, target_obj, target_method):
            self._target_obj = target_obj
            self._target_method = target_method

        @property
        def target_obj(self):
            return self._target_obj

        @property
        def target_method(self):
            return self._target_method

    def _inject_methods_from(self, target):
        for name, m in inspect.getmembers(type(target), lambda x: inspect.isfunction(x) or inspect.ismethod(x)):
            if not name.startswith('_'):
                own_func = partial(self.__target_method_wrapper, Injecter.Target(target, m))
                self.__setattr__(name, own_func)

    def __target_method_wrapper(self, target, *args, **kwargs):
        return target.target_method(target.target_obj, *args, **kwargs)
